cypress_script:
describe('Forgotten Login Lookup Form', () => {
  it('should successfully submit the form with valid data', () => {
    cy.visit('https://parabank.parasoft.com/parabank/lookup.htm');
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="address.street"]').type('123 Main St');
    cy.get('input[name="address.city"]').type('Anytown');
    cy.get('input[name="address.state"]').type('CA');
    cy.get('input[name="address.zipCode"]').type('90210');
    cy.get('input[name="ssn"]').type('123-45-6789');
    cy.get('input[value="Find My Login Info"]').click();
    // Assert that the URL changes to a new page (not specified in inventory)
  });

  it('should not submit the form when required fields are empty', () => {
    cy.visit('https://parabank.parasoft.com/parabank/lookup.htm');
    cy.get('input[value="Find My Login Info"]').click();
    // Assert that the URL remains the same
    cy.url().should('eq', 'https://parabank.parasoft.com/parabank/lookup.htm');
    // Assert that the 'Customer Lookup' heading is still visible
    cy.contains('Customer Lookup').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Forgotten Login Lookup Form', () => {
  test('should successfully submit the form with valid data', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/lookup.htm');
    await page.fill('input[name="firstName"]', 'John');
    await page.fill('input[name="lastName"]', 'Doe');
    await page.fill('input[name="address.street"]', '123 Main St');
    await page.fill('input[name="address.city"]', 'Anytown');
    await page.fill('input[name="address.state"]', 'CA');
    await page.fill('input[name="address.zipCode"]', '90210');
    await page.fill('input[name="ssn"]', '123-45-6789');
    await page.click('input[value="Find My Login Info"]');
    // Assert that the URL changes to a new page (not specified in inventory)
  });

  test('should not submit the form when required fields are empty', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/lookup.htm');
    await page.click('input[value="Find My Login Info"]');
    // Assert that the URL remains the same
    await expect(page).toHaveURL('https://parabank.parasoft.com/parabank/lookup.htm');
    // Assert that the 'Customer Lookup' heading is still visible
    await expect(page.locator('text=Customer Lookup')).toBeVisible();
  });
});
